Translate("esMX", "ironforge", {
	title = "Forjaz",
	aliases = { "ciudad de Forjaz" },
	sections = {
		{
			title = "Resumen",
			text = [=[Forjaz es la capital del {link:kingdom-of-ironforge}Reino de Forjaz{/link} y la ciudad más antigua de los {link:dwarves}enanos{/link}. Está tallada en el corazón de una montaña de {link:dun-morogh}Dun Morogh{/link}, y ni siquiera la {link:horde}Horda{/link} en la cima de su poder logró tomarla. En su centro, los fuegos de la {link:the-great-forge}Gran Forja{/link} arden día y noche, y los ríos de metal fundido que los alimentan iluminan toda la ciudad de rojo y oro. Alrededor de la forja se hallan las salas del comercio, del saber, de la magia y de la guerra, y bajo el trono se hallan salas aún más antiguas.]=],
		},
		{
			title = "Orígenes",
			text = [=[Los enanos sostienen que Forjaz es su primer hogar, y que su pueblo fue moldeado con la piedra de estas montañas en eras pasadas. Ninguna crónica registra el año en que se excavaron sus primeras salas. Durante largas eras, todos los enanos fueron gobernados desde Forjaz por un único gran rey. Cuando murió, los clanes Barbabronce, Martillo Salvaje y Hierro Negro lucharon por su trono. Los Barbabronce conservaron la ciudad, y cuando los {link:dark-iron-dwarves}Hierro Negro{/link} volvieron para tomarla, fueron derrotados ante sus puertas.]=],
		},
		{
			title = "El presente",
			text = [=[El rey {link:magni-bronzebeard}Magni Bronzebeard{/link} gobierna desde {link:high-seat}el High Seat{/link}, con el Senado de Forjaz a su lado y no siempre de acuerdo con él. Gran parte de su ejército está lejos, sirviendo a la {link:alliance}Alianza{/link}. Su hermano {link:muradin-bronzebeard}Muradin Bronzebeard{/link} se perdió en el norte, y su hermano {link:brann-bronzebeard}Brann Bronzebeard{/link} recorre el mundo. Su hija Moira ha desaparecido, y él cree que se la llevó el emperador {link:dark-iron-dwarves}Hierro Negro{/link}. Los gnomos de {link:gnomeregan}Gnomeregan{/link} viven en {link:tinker-town}Tinker Town{/link} desde que cayó su ciudad, y sus manitas llenan las salas de ruido. Ahora se han abierto los antiguos pasajes sellados bajo el High Seat. Algo ha estado perturbando las tumbas de los thanes, y han descubierto a los Hierro Negro excavando hacia ellas.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Los enanos Barbabronce.{/b} Herreros, mercaderes, soldados, sacerdotes y eruditos llenan los distritos de la ciudad.
• {b}Los {link:gnomeregan-exiles}Exiliados de Gnomeregan{/link}.{/b} El Manitas Mayor {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} guía a su pueblo desde {link:tinker-town}Tinker Town{/link}.
• {b}La Liga de Expedicionarios.{/b} Desde el {link:hall-of-explorers}Hall of Explorers{/link}, la {link:explorers-league}Liga de Expedicionarios{/link} envía a sus miembros a ruinas de todo el mundo.
• {b}Viajeros de la {link:alliance}Alianza{/link}.{/b} Los humanos van y vienen en el tren gnómico desde {link:stormwind-city}Ventormenta{/link}.
• {b}Ladrones en la oscuridad.{/b} En la Forlorn Cavern, una sociedad llamada el Círculo Oculto trama quedarse con una parte de las riquezas del rey.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}Los Tres Martillos.{/b} Los Barbabronce defendieron Forjaz contra sus parientes. Una tablilla de tratado guardada en las cámaras reales recoge la paz que siguió: la firmaron los Barbabronce y los Martillo Salvaje, y nunca los {link:dark-iron-dwarves}Hierro Negro{/link}.
• {b}La {link:second-war}Segunda Guerra{/link}.{/b} La {link:horde}Horda{/link} arrasó Khaz Modan, pero Forjaz resistió. Los enanos se unieron a la {link:alliance}Alianza de Lordaeron{/link} y lucharon hasta que la Horda fue derrotada.
• {b}La {link:third-war}Tercera Guerra{/link}.{/b} {link:muradin-bronzebeard}Muradin{/link} fue a Rasganorte y no regresó. Los enanos lo cuentan entre los muertos.
• {b}La caída de {link:gnomeregan}Gnomeregan{/link}.{/b} Cuando los gnomos perdieron su ciudad, {link:magni-bronzebeard}Magni{/link} les abrió Forjaz.
• {b}El presente.{/b} Las salas bajo {link:high-seat}el High Seat{/link} vuelven a estar abiertas, y el reino descubre que su enemigo más antiguo ha estado excavando hacia sus muertos más antiguos.]=],
		},
		{
			title = "Saber de la montaña",
			text = [=[• Un cantero de Forjaz talló un monumento para Sully Balloo, un soldado que murió lejos de casa, con piedra fina traída de las ruinas de {link:lordaeron}Lordaeron{/link}. El propio rey lo pagó.
• Los montañeros que mueren en las nieves de {link:dun-morogh}Dun Morogh{/link} vuelven a casa como rifles, con sus nombres tallados en las culatas.]=],
		},
	},
})

Translate("esMX", "the-great-forge", {
	title = "The Great Forge",
	aliases = { "Great Forge", "Gran Forja" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Gran Forja ocupa la sala central de {link:ironforge}Forjaz{/link}. El metal fundido cae desde las alturas a grandes pilas, y a su alrededor los herreros de la ciudad trabajan en yunques que nunca se enfrían. El calor y la luz de la forja llegan a todos los distritos, y su martilleo es el sonido que los enanos llaman hogar. Comerciantes, instructores y mensajeros abarrotan su anillo, y los grifos de la ciudad van y vienen desde la terraza cercana. Ningún otro lugar de la ciudad está tan concurrido, y ninguno es tan querido.]=],
		},
	},
})

Translate("esMX", "the-commons", {
	title = "The Commons",
	sections = {
		{
			title = "Resumen",
			text = [=[The Commons es el distrito del comercio de {link:ironforge}Forjaz{/link}. Aquí se encuentran la Cámara de Forjaz, donde se guardan bajo vigilancia las riquezas de la ciudad y las de sus visitantes, la gran casa de subastas y la posada del tabernero Firebrew. Mercaderes de todos los pueblos de la {link:alliance}Alianza{/link} vienen aquí, y el distrito resuena con el regateo desde la primera hora hasta la última. Los viajeros que llevan mucho tiempo en el camino acuden a la posada en busca de un hogar cálido y una cerveza fuerte antes de seguir adelante.]=],
		},
	},
})

Translate("esMX", "hall-of-explorers", {
	title = "Hall of Explorers",
	aliases = { "Asamblea de Expedicionarios" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Hall of Explorers es la sede de la {link:explorers-league}Liga de Expedicionarios{/link}. Sus galerías guardan reliquias traídas de ruinas de todo el mundo, su biblioteca conserva los libros y mapas de la Liga, y sus eruditos discuten sobre los verdaderos orígenes del pueblo {link:dwarves}enano{/link}. El alto explorador {link:high-explorer-magellas}Magellas{/link} preside aquí. El consejero {link:advisor-belgrum}Belgrum{/link}, el historiador {link:historian-karnik}Karnik{/link} y el prospector Stormpike atienden sus asuntos en la sala, y las noticias de las excavaciones de las {link:badlands}Tierras Inhóspitas{/link} y de {link:loch-modan}Loch Modan{/link} llegan aquí antes que a ningún otro sitio.]=],
		},
	},
})

Translate("esMX", "tinker-town", {
	title = "Tinker Town",
	sections = {
		{
			title = "Resumen",
			text = [=[Tinker Town es el distrito que el {link:magni-bronzebeard}rey Magni{/link} entregó a los gnomos tras la caída de {link:gnomeregan}Gnomeregan{/link}. Traquetea con engranajes y sisea con vapor, y sus talleres están atestados de artefactos a medio construir. El {link:gelbin-mekkatorque}Manitas Mayor Mekkatorque{/link} mantiene aquí su corte en el exilio. Desde Tinker Town, el Tranvía Subterráneo corre muy por debajo de la tierra hasta {link:stormwind-city}Ventormenta{/link}, y los manitas de Gnomeregan envían voluntarios de vuelta a su ciudad perdida para salvar lo que puedan.]=],
		},
	},
})

Translate("esMX", "the-mystic-ward", {
	title = "The Mystic Ward",
	aliases = { "Mystic Ward" },
	sections = {
		{
			title = "Resumen",
			text = [=[The Mystic Ward es el barrio de la ciudad dedicado a la fe y a la magia. Los sacerdotes de la {link:holy-light}Luz Sagrada{/link} sirven en el Hall of Mysteries, y los magos estudian en las salas que lo rodean. Es un lugar más tranquilo que el resto de {link:ironforge}Forjaz{/link}, lejos del rugido de la forja, y quienes buscan las artes superiores encuentran aquí a sus maestros.]=],
		},
	},
})

Translate("esMX", "the-military-ward", {
	title = "The Military Ward",
	aliases = { "Military Ward" },
	sections = {
		{
			title = "Resumen",
			text = [=[The Military Ward es la fortaleza dentro de la fortaleza. Su Hall of Arms entrena a los guerreros de {link:ironforge}Forjaz{/link} bajo la guía de Muren Stormpike, que enseña que un guerrero nunca da la espalda a un enemigo. Los soldados del rey se entrenan aquí antes de marchar a los frentes de la {link:alliance}Alianza{/link}. Es un lugar duro, y los enanos que sirven en él están orgullosos de ello.]=],
		},
	},
})

Translate("esMX", "high-seat", {
	title = "High Seat",
	aliases = { "el High Seat" },
	sections = {
		{
			title = "Resumen",
			text = [=[El High Seat es la sala del trono de {link:ironforge}Forjaz{/link}, elevada sobre las salas occidentales de la ciudad. Aquí celebra su corte el {link:magni-bronzebeard}rey Magni Bronzebeard{/link}, custodiado por la Guardia Real de Hierro. Los senadores de Forjaz van y vienen con los asuntos del reino, y el historiador real mantiene la memoria del reino cerca del trono. Una puerta a un lado de la sala, sellada durante mucho tiempo, está ahora abierta. Más allá, un camino desciende hacia {link:old-ironforge}Old Ironforge{/link}.]=],
		},
	},
})

Translate("esMX", "old-ironforge", {
	title = "Old Ironforge",
	sections = {
		{
			title = "Resumen",
			text = [=[Old Ironforge se encuentra bajo {link:high-seat}el High Seat{/link} y es la parte más antigua de la ciudad. Durante generaciones sus puertas estuvieron cerradas, y pocos enanos vivos habían caminado por ella. Ahora el paso está abierto. Un largo camino desciende serpenteando por viejas salas hasta las cavernas de abajo, donde el {link:hall-of-thanes}Hall of Thanes{/link} guarda las tumbas de los grandes enanos del pasado. Los guardianes de esas tumbas han oído ruidos extraños en las criptas, y los muertos que yacen en ellas han empezado a agitarse.]=],
		},
	},
})

Translate("esMX", "magni-bronzebeard", {
	title = "Magni Bronzebeard",
	subtitle = "Rey de Forjaz",
	found = "El High Seat, Forjaz",
	hint = "Pida audiencia al rey en el High Seat.",
	allegiance = "Reino de Forjaz · Alianza",
	aliases = { "Magni", "rey Magni", "rey Magni Bronzebeard" },
	sections = {
		{
			title = "Resumen",
			text = [=[Magni Bronzebeard es el rey de {link:ironforge}Forjaz{/link} y señor de los enanos Barbabronce. Es el mayor de tres hermanos, y sobre su cabeza descansa la corona más pesada de Khaz Modan. Desde {link:high-seat}el High Seat{/link} gobierna a un pueblo orgulloso y terco, negocia con un Senado que no siempre piensa como él y se mantiene fiel a una {link:alliance}Alianza{/link} que le ha costado muy cara.]=],
		},
		{
			title = "Importancia",
			text = [=[Magni es uno de los pilares de la {link:alliance}Alianza{/link}. Cuando la {link:horde}Horda{/link} arrasó Khaz Modan en la {link:second-war}Segunda Guerra{/link}, su pueblo no olvidó quién estuvo a su lado, y desde entonces {link:ironforge}Forjaz{/link} ha cumplido su palabra con la humanidad. Cuando los gnomos perdieron su ciudad, él los acogió. Cuando la Alianza llama, sus soldados acuden. La carga de Magni es que cada una de esas decisiones la ha pagado su propio pueblo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige el {link:kingdom-of-ironforge}Reino de Forjaz{/link} y ocupa su asiento en la {link:alliance}Alianza{/link}.
• Envía a su ejército al extranjero a luchar junto a la Alianza, aunque eso deje sus propias tierras poco protegidas.
• Dio un hogar en su ciudad a los {link:gnomeregan-exiles}exiliados de Gnomeregan{/link}.
• Llora a su hermano {link:muradin-bronzebeard}Muradin{/link}, perdido en Rasganorte. Su hermano {link:brann-bronzebeard}Brann{/link} está lejos, ocupado en los asuntos de la Liga.
• Busca a su hija Moira, que desapareció en {link:burning-steppes}Las Estepas Ardientes{/link}, y culpa de ello al emperador {link:dark-iron-dwarves}Hierro Negro{/link}.]=],
		},
	},
	chapters = {
		{
			title = "El tributo de un rey",
			hint = "Cumpla el deseo del rey para la viuda de un soldado caído.",
			text = [=[Cuando la viuda de Sully Balloo le escribió, Magni no fingió que la muerte de su marido hubiera sido otra cosa que una pérdida. Dijo que cada {link:dwarves}enano{/link} que cae por la {link:alliance}Alianza{/link} pesa sobre su alma. No podía devolverle a Sully, así que hizo que el gran cantero le tallara un monumento de granito de {link:lordaeron}Lordaeron{/link}, con la esperanza de que quienes vinieran después recordaran por quién morían esos soldados.]=],
		},
		{
			title = "El Tratado de Entendimiento",
			hint = "Recupere un tratado antiguo de las cámaras bajo la ciudad.",
			text = [=[Del Relicario de los Reyes, bajo {link:ironforge}Forjaz{/link}, salió una tablilla de piedra. Magni la reconoció al instante. Era la paz acordada tras la guerra de los tres clanes, en los días de su antepasado Madoran, el primer Barbabronce que gobernó Forjaz. Los Barbabronce la habían firmado, y los Martillo Salvaje la habían firmado. Los {link:dark-iron-dwarves}Hierro Negro{/link} no.]=],
		},
		{
			title = "Bajo nuestros pies",
			hint = "Ponga fin a la incursión Hierro Negro bajo Forjaz.",
			text = [=[La noticia de que se había hallado una fuerza {link:dark-iron-dwarves}Hierro Negro{/link} bajo la ciudad tomó al rey por sorpresa. Se alegró de saber que su comandante había muerto, y ordenó de inmediato sellar las brechas y reforzar las salas inferiores. También envió sus cálidos saludos a un viejo amigo Martillo Salvaje, el vidente de la tierra {link:earthseer-farsen}Farsen{/link}, junto con la exigencia de que Farsen fuera a visitarlo como es debido.]=],
		},
		{
			title = "La princesa perdida",
			hint = "Averigüe qué ha sido de la hija del rey.",
			text = [=[Magni lloró al hablar de Moira. Había enviado a sus hombres a buscar en {link:burning-steppes}Las Estepas Ardientes{/link}, y la única pista que encontraron apuntaba a las profundidades de {link:blackrock-mountain}Roca Negra{/link}. Creía que era cautiva del emperador {link:dark-iron-dwarves}Hierro Negro{/link}, Dagran {link:ruins-of-thaurissan}Thaurissan{/link}, atada por sus hechizos, y quería al emperador muerto. Cuando le llegó la verdad, fue peor de lo que había temido. Moira llevaba en su seno al hijo de Thaurissan, y envió aviso de que el heredero de {link:ironforge}Forjaz{/link} sería un Hierro Negro. Magni solo pudo decir que, incluso muerto, Thaurissan había ganado.]=],
		},
	},
	mentions = {
		{ text = "El tributo de un rey" },
		{ text = "La negociación de la paz" },
		{ text = "Kharan Mighthammer" },
		{ text = "El portador de malas noticias" },
		{ text = "El destino del reino" },
	},
	bonds = {
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "su hermano, perdido en Rasganorte" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "su hermano menor" },
		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "su aliado y huésped" },
		{ id = "earthseer-farsen", name = "Vidente de la tierra Farsen", note = "un viejo amigo Martillo Salvaje" },
		{ id = "royal-historian-archesonus", name = "Historiadora real Archesonus", note = "guarda la memoria de su reino" },
		{ id = "senator-barin-redstone", name = "Senador Barin Redstone", note = "un senador de su corte" },
	},
})

Translate("esMX", "muradin-bronzebeard", {
	title = "Muradin Bronzebeard",
	subtitle = "Hermano del rey",
	found = "Perdido en Rasganorte",
	allegiance = "Reino de Forjaz",
	aliases = { "Muradin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Muradin Bronzebeard es el hermano del {link:magni-bronzebeard}rey Magni{/link}. Fue uno de los guerreros más poderosos de {link:ironforge}Forjaz{/link}, un {link:dwarves}enano{/link} de gran fuerza, palabra franca y corazón cálido. En la {link:third-war}Tercera Guerra{/link} partió hacia el continente helado de Rasganorte, y no volvió a casa. Forjaz lo cuenta entre sus muertos.]=],
		},
		{
			title = "Importancia",
			text = [=[Muradin estaba unido a la casa de {link:lordaeron}Lordaeron{/link} por algo más que una alianza. Había sido maestro de armas del joven príncipe {link:arthas-menethil}Arthas Menethil{/link}, y ambos eran amigos. Ese vínculo convirtió a Muradin en testigo de los primeros pasos del príncipe hacia la ruina. También le costó la vida, o eso se cree en {link:ironforge}Forjaz{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Sirvió a la {link:alliance}Alianza{/link} y era conocido en las cortes de los reinos humanos.
• Enseñó al príncipe de {link:lordaeron}Lordaeron{/link} el arte de la espada y del martillo.
• Dirigió una expedición de enanos a Rasganorte en busca de una legendaria runa espada llamada Agonía de Escarcha.
• Luchó junto a {link:arthas-menethil}Arthas{/link} contra los no-muertos en los páramos helados.]=],
		},
		{
			title = "El viaje al norte",
			text = [=[La compañía de Muradin llevaba mucho tiempo buscando Agonía de Escarcha en Rasganorte cuando se encontró con {link:arthas-menethil}Arthas{/link}, que había seguido a un señor del terror a través del mar. Los enanos y el príncipe unieron fuerzas contra los no-muertos. Muradin se inquietó al observar a su antiguo pupilo. Arthas había quemado sus propios barcos para que sus hombres no pudieran volver a casa, y su odio al enemigo se había convertido en lo único por lo que parecía vivir.

Por fin encontraron la espada en una caverna helada, sellada en hielo y custodiada. Muradin leyó la advertencia allí grabada y suplicó a Arthas que la dejara. El príncipe no quiso. Cuando Arthas liberó la espada, el hielo estalló en pedazos, y un fragmento derribó a Muradin. Arthas tomó Agonía de Escarcha y siguió adelante sin él.]=],
		},
		{
			title = "En Forjaz",
			text = [=[Los enanos recuerdan a Muradin como un héroe de la {link:alliance}Alianza{/link} y el hermano de su rey. Su pérdida es un peso más que carga {link:magni-bronzebeard}Magni{/link}, junto a un ejército lejos de casa y una hija arrebatada por los {link:dark-iron-dwarves}Hierro Negro{/link}. En las salas de {link:ironforge}Forjaz{/link} su nombre se pronuncia con pesar, y con el orgullo terco que los enanos guardan para quienes cayeron haciendo lo que creían justo.]=],
		},
		{
			title = "Sin registro",
			text = [=[En {link:ironforge}Forjaz{/link} no se sabe qué fue de Muradin después de aquel día. Su pueblo cree que murió en el hielo. Ninguna crónica conocida por los enanos dice otra cosa.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "su hermano" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "su hermano" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "su pupilo" },
	},
})

Translate("esMX", "brann-bronzebeard", {
	title = "Brann Bronzebeard",
	subtitle = "Explorador de la Liga de Expedicionarios",
	found = "Viajando lejos de Forjaz",
	allegiance = "Reino de Forjaz · Liga de Expedicionarios",
	aliases = { "Brann" },
	sections = {
		{
			title = "Resumen",
			text = [=[Brann Bronzebeard es el hermano menor del {link:magni-bronzebeard}rey Magni{/link}. Si Magni tomó la corona y {link:muradin-bronzebeard}Muradin{/link} el martillo, Brann tomó el mapa y la linterna. Es el explorador más famoso de la {link:explorers-league}Liga de Expedicionarios{/link}, un {link:dwarves}enano{/link} que prefiere dormir en una ruina titánica antes que en una cama real.]=],
		},
		{
			title = "Importancia",
			text = [=[Brann es el espíritu vivo de la gran pregunta de la Liga: ¿de dónde vinieron los enanos? Ha pasado su vida buscando la respuesta en los lugares antiguos del mundo, y su nombre abre puertas que se cierran a exploradores menores. Los eruditos de la Liga en el {link:hall-of-explorers}Hall of Explorers{/link} continúan su trabajo mientras él viaja.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Ha explorado ruinas por todos los {link:eastern-kingdoms}Reinos del Este{/link} y más allá en busca de los orígenes de los enanos.
• Se le cuenta entre los miembros principales de la {link:explorers-league}Liga de Expedicionarios{/link}.]=],
		},
		{
			title = "La gran pregunta",
			text = [=[La pregunta que mueve a Brann es la misma que se hace toda la Liga: ¿fueron los enanos realmente moldeados en piedra por los titanes? En su ausencia, sus colegas se han acercado a una respuesta más que nunca. De las profundidades de {link:uldaman}Uldaman{/link} han traído registros de las obras de los titanes, y esos registros apuntan a cámaras aún mayores en los desiertos del sur. Es la clase de descubrimiento al que Brann ha dedicado su vida.]=],
		},
		{
			title = "Sin registro",
			text = [=[Los viajes de Brann lo han llevado lejos de {link:ironforge}Forjaz{/link}, y nadie en la ciudad sabe decir dónde está ahora. De sus viajes, las salas del {link:high-seat}High Seat{/link} solo oyen rumores. Esta entrada solo recoge lo que es seguro.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "su hermano mayor" },
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "su hermano" },
		{ id = "high-explorer-magellas", name = "Alto explorador Magellas", note = "dirige la Liga en su ausencia" },
	},
})

Translate("esMX", "gelbin-mekkatorque", {
	title = "Gelbin Mekkatorque",
	subtitle = "Manitas Mayor, rey de los gnomos",
	found = "Tinker Town, Forjaz",
	hint = "Busque al Manitas Mayor en Tinker Town.",
	allegiance = "Exiliados de Gnomeregan · Alianza",
	aliases = { "Mekkatorque", "Manitas Mayor Mekkatorque", "Gelbin", "Manitas Mayor Gelbin Mekkatorque" },
	sections = {
		{
			title = "Resumen",
			text = [=[Gelbin Mekkatorque es el Manitas Mayor de los gnomos, el rey de un pueblo que ha perdido su reino. Gobernaba en {link:gnomeregan}Gnomeregan{/link} cuando la ciudad era grande. Ahora gobierna desde un taller de {link:tinker-town}Tinker Town{/link}, como huésped de los enanos, con la mayor parte de su pueblo muerta, envenenada o dispersa. No ha perdido ni el ingenio ni la voluntad. Tiene intención de volver a casa.]=],
		},
		{
			title = "Importancia",
			text = [=[Mekkatorque mantiene unidos a los gnomos. Sin él, los exiliados serían una multitud de refugiados. Con él, siguen siendo una nación, con un asiento entre los pueblos de la {link:alliance}Alianza{/link} y un derecho sobre su ciudad al que nunca han renunciado.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirigió a los gnomos de {link:gnomeregan}Gnomeregan{/link} como Manitas Mayor.
• Cuando los troggs se alzaron bajo la ciudad, volvió contra ellos las propias artes de los gnomos en una purga desesperada, y la ciudad quedó envenenada.
• Condujo a los supervivientes hasta {link:ironforge}Forjaz{/link} e hizo de {link:tinker-town}Tinker Town{/link} su hogar.
• Envía voluntarios de vuelta a Gnomeregan para recuperar lo que quedó atrás y golpear al traidor que la ocupa.]=],
		},
		{
			title = "La caída de la ciudad",
			text = [=[Ninguna crónica registra el año en que los troggs subieron de las profundidades bajo {link:gnomeregan}Gnomeregan{/link}. Llegaron en gran número, y la ciudad no pudo contenerlos. Mekkatorque decidió purgarlos con un arma fabricada por los propios gnomos. Mató a los troggs, pero también mató a muchísimos gnomos, y dejó la ciudad empapada de veneno. Muchos de los que sobrevivieron se transformaron en leprosos enfermos y sin juicio. El resto huyó a las nieves de {link:dun-morogh}Dun Morogh{/link}.]=],
		},
		{
			title = "La corte en el exilio",
			text = [=[En {link:tinker-town}Tinker Town{/link}, el pueblo del Manitas Mayor no ha dejado de trabajar. El maestro manitas Overspark espera reparar a su pobre Techbot, cuya mente quedó invertida en la caída. El maestro mecánico Castpipe organiza grupos para recuperar registros vitales de las terminales de la ciudad. Klockmort Spannerspan necesita las piezas que nadie recordó llevarse en la huida. Cada una de esas misiones es un pequeño paso de vuelta a {link:gnomeregan}Gnomeregan{/link}, y Mekkatorque las alienta todas.]=],
		},
	},
	chapters = {
		{
			title = "La gran traición",
			hint = "Abata al traidor que gobierna Gnomeregan.",
			text = [=[Mekkatorque había confiado en {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link}. Nunca imaginó que Thermaplugg lo traicionaría a él y a todo el pueblo {link:gnomes}gnomo{/link}, y aún no entiende por qué, pues el poder y la riqueza le habrían llegado a Thermaplugg con el tiempo. Ahora el traidor se sienta en las ruinas, rey de la nada. Cuando llegó la noticia de que Thermaplugg había caído, Mekkatorque se permitió una broma sombría, y luego dirigió su mente al día en que los gnomos recuperarían su ciudad.]=],
		},
	},
	mentions = {
		{ text = "Rescate de datos" },
		{ text = "¡Salven el cerebro de Techbot!" },
		{ text = "Artificiales esenciales" },
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Mekigeniero Thermaplugg", note = "el traidor" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "su anfitrión y aliado" },
		{ id = "razzle-sprysprocket", name = "Razzle Sprysprocket", note = "uno de los suyos que busca una cura" },
	},
})

Translate("esMX", "royal-historian-archesonus", {
	title = "Historiadora real Archesonus",
	subtitle = "Historiadora real de Forjaz",
	found = "El High Seat, junto al trono",
	hint = [=[Hable con la historiadora que guarda la memoria del reino junto al trono.]=],
	allegiance = "Reino de Forjaz",
	aliases = { "Archesonus" },
	sections = {
		{
			title = "Resumen",
			text = [=[La historiadora real Archesonus guarda la memoria de {link:ironforge}Forjaz{/link} junto al trono del {link:magni-bronzebeard}rey Magni{/link}. Cualquiera que lo pida puede oír de ella la historia del reino. El relato que cuenta con más gravedad es el de los {link:dark-iron-dwarves}Hierro Negro{/link} y el de la ciudad de {link:ruins-of-thaurissan}Thaurissan{/link}, que ardió.]=],
		},
		{
			title = "Importancia",
			text = [=[Archesonus es la voz del pasado de {link:ironforge}Forjaz{/link}. Los enanos son un pueblo de larga memoria, y en {link:high-seat}el High Seat{/link} esa memoria tiene una guardiana. Su conocimiento de los {link:dark-iron-dwarves}Hierro Negro{/link} se ha vuelto urgente, pues el viejo enemigo del reino vuelve a moverse.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Enseña la historia de {link:ironforge}Forjaz{/link} a quienes acuden al {link:high-seat}High Seat{/link}.
• Envía buscadores a las {link:ruins-of-thaurissan}Ruinas de Thaurissan{/link}, en {link:burning-steppes}Las Estepas Ardientes{/link}, para leer las reliquias que quedaron allí.]=],
		},
	},
	chapters = {
		{
			title = "La historia de Thaurissan",
			hint = "Pida a la historiadora real la historia de los Hierro Negro.",
			text = [=[Archesonus empieza muy atrás, cuando los {link:dark-iron-dwarves}Hierro Negro{/link} tenían una ciudad propia. {link:ruins-of-thaurissan}Thaurissan{/link} se alzaba en un país verde que hoy son {link:burning-steppes}Las Estepas Ardientes{/link}, y en aquellos días los clanes enanos estaban en guerra entre sí. Entonces una explosión terrible la destruyó, y la tierra en millas a la redonda quedó reducida a cenizas. Qué causó la explosión, admite ella, ningún historiador puede decirlo. Los Hierro Negro que sobrevivieron entraron en la montaña y empezaron de nuevo. De las cenizas se alzó la Cumbre de {link:blackrock-mountain}Roca Negra{/link}, y se fortificó el Caldero de {link:searing-gorge}La Garganta de Fuego{/link}. Pronto hubo susurros de un mal antiguo que gobernaba el reino Hierro Negro desde dentro. Su relato termina en el presente. Cada año se ve más a menudo a los Hierro Negro en la superficie. Han levantado fuertes en las {link:badlands}Tierras Inhóspitas{/link}, han enviado grandes grupos a {link:uldaman}Uldaman{/link} e incluso han atacado la presa de {link:loch-modan}Loch Modan{/link}.]=],
		},
		{
			title = "Las ruinas humeantes",
			hint = [=[Lea las reliquias de Thaurissan y traiga sus recuerdos de vuelta.]=],
			text = [=[Las reliquias de la ciudad en ruinas guardan recuerdos, y quienes las tocan los conservan. Una criatura de llama pura. Ocho enanos {link:dark-iron-dwarves}Hierro Negro{/link} en un ritual. Uno de ellos solo al final, arrodillado entre siete muertos ante un pilar de fuego. Archesonus escuchó esos recuerdos y dijo que explicaban muchas cosas, y que había mucho más por aprender.]=],
		},
	},
	mentions = {
		{
			text = [=[Las ruinas humeantes de {link:ruins-of-thaurissan}Thaurissan{/link}]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "su rey" },
	},
})

Translate("esMX", "high-explorer-magellas", {
	title = "Alto explorador Magellas",
	subtitle = "Alto explorador de la Liga de Expedicionarios",
	found = "El Hall of Explorers",
	hint = "Hable con el alto explorador en el Hall of Explorers.",
	allegiance = "Liga de Expedicionarios",
	aliases = { "Magellas" },
	sections = {
		{
			title = "Resumen",
			text = [=[El alto explorador Magellas dirige la {link:explorers-league}Liga de Expedicionarios{/link} desde el {link:hall-of-explorers}Hall of Explorers{/link}. Es un {link:dwarves}enano{/link} ocupado, y se lo hace saber a los visitantes. Sin embargo, nadie en {link:ironforge}Forjaz{/link} se entusiasma más con un descubrimiento de verdad, y cuando uno llega a su mesa, su dignidad sale volando por la ventana.]=],
		},
		{
			title = "Importancia",
			text = [=[Bajo Magellas, la Liga persigue la pregunta que más le importa: la prueba de que los enanos fueron moldeados en piedra por los titanes, a quienes los viejos registros llaman los Creadores. Él cree que esa prueba puede estar al alcance.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige las expediciones de la Liga y recompensa con la cámara de la Liga a quienes la sirven.
• Estudia los {link:lore-keeper-of-norgannon}Discos de Norgannon{/link} en miniatura traídos de {link:uldaman}Uldaman{/link}.
• Dirige la mirada de la Liga hacia {link:valley-of-the-watchers}Uldum{/link}, muy al sur, en {link:tanaris}Tanaris{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Los discos de platino",
			hint = "Lleve a la Liga un hallazgo de las profundidades de Uldaman.",
			text = [=[Cuando pusieron ante él una copia en miniatura de los {link:lore-keeper-of-norgannon}Discos de Norgannon{/link}, Magellas preguntó dónde se había encontrado, y luego volvió a preguntarlo, y no podía creer las respuestas. Lo llamó el hallazgo del siglo. Si los discos decían lo que él pensaba, zanjarían de una vez por todas la vieja cuestión del origen de los enanos.]=],
		},
		{
			title = "Uldum aguarda",
			hint = "Siga los discos hasta las puertas de Uldum e informe.",
			text = [=[Los discos llevaron a {link:valley-of-the-watchers}las puertas selladas de Uldum{/link}, donde otro vigía de piedra habló de unas placas que faltaban. Magellas coincidió con sus eruditos en que la búsqueda debía esperar hasta saber dónde buscar. Prometió que, llegado el momento, la Liga enviaría de nuevo al campo a las mismas manos.]=],
		},
	},
	mentions = {
		{ text = "Los discos de platino" },
		{ text = "Presagios de {link:valley-of-the-watchers}Uldum{/link}" },
	},
	bonds = {
		{ id = "historian-karnik", name = "Historiador Karnik", note = "su erudito" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "el explorador más famoso de la Liga" },
	},
})

Translate("esMX", "advisor-belgrum", {
	title = "Consejero Belgrum",
	subtitle = "Consejero del rey",
	found = "El Hall of Explorers",
	hint = [=[Encuentre al consejero del rey entre los eruditos del Hall of Explorers.]=],
