	},
	mentions = {
		{ text = "Aviso de una amenaza" },
		{ text = "Un embajador del mal" },
		{ text = "Las tablillas perdidas de Voluntad" },
	},
	bonds = {
		{ id = "historian-karnik", name = "Historiador Karnik", note = "le trae noticias" },
	},
})

Translate("esMX", "historian-karnik", {
	title = "Historiador Karnik",
	subtitle = "Historiador de la Liga de Expedicionarios",
	found = "El Hall of Explorers",
	hint = [=[Encuentre al historiador de la Liga que llora a su amigo Hammertoe.]=],
	allegiance = "Liga de Expedicionarios",
	aliases = { "Karnik" },
	sections = {
		{
			title = "Resumen",
			text = [=[El historiador Karnik trabajó con el explorador Hammertoe para encontrar los artefactos perdidos de {link:uldaman}Uldaman{/link}, hasta que los Shadowforge mataron a Hammertoe por lo que sabía. Karnik todavía habla con el espíritu de su amigo. También estudia los lugares antiguos del sur, y ha encontrado pistas sobre el {link:valley-of-the-watchers}Valle de los Vigías{/link}, en {link:tanaris}el desierto de Tanaris{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Karnik es la memoria de la Liga sobre lo que ha costado {link:uldaman}Uldaman{/link}. A través de él, la muerte de Hammertoe se convirtió en una causa de todo el reino.]=],
		},
	},
	mentions = {
		{ text = "Perspectiva de fe" },
		{ text = "Aviso de una amenaza" },
		{ text = "A ver qué pasa" },
		{ text = "Regreso a {link:ironforge}Forjaz{/link}" },
	},
	bonds = {
		{ id = "advisor-belgrum", name = "Consejero Belgrum", note = "habla en nombre del rey" },
		{ id = "high-explorer-magellas", name = "Alto explorador Magellas", note = "su superior" },
	},
})

Translate("esMX", "prospector-stormpike", {
	title = "Prospector Stormpike",
	subtitle = "Prospector de la Liga de Expedicionarios",
	found = "El Hall of Explorers",
	hint = [=[Encuentre al prospector de mal genio en el Hall of Explorers.]=],
	allegiance = "Liga de Expedicionarios",
	sections = {
		{
			title = "Resumen",
			text = [=[El prospector Stormpike supervisa las excavaciones de la Liga desde el {link:hall-of-explorers}Hall of Explorers{/link}, y no soporta de buen grado los asuntos triviales. Se enfada enseguida cuando una excavación avanza despacio, y aún más deprisa cuando falta pólvora explosiva. Bajo su genio hay lealtad: cuando los troggs invadieron {link:uldaman}Uldaman{/link}, su primer pensamiento fue para su amigo {link:the-lost-dwarves}Baelog{/link} y los enanos atrapados tras las líneas.]=],
		},
		{
			title = "Importancia",
			text = [=[Stormpike mantiene abastecidos a los excavadores de la Liga y en marcha sus expediciones, desde la excavación de {link:prospector-ironband}Ironband{/link} en {link:loch-modan}Loch Modan{/link} hasta las profundidades de {link:uldaman}Uldaman{/link}.]=],
		},
	},
	mentions = {
		{ text = "Informe a {link:ironforge}Forjaz{/link}" },
		{ text = "Pólvora para {link:prospector-ironband}Ironband{/link}" },
		{ text = "{link:the-lost-dwarves}Los enanos perdidos{/link}" },
	},
	bonds = {
		{ id = "high-explorer-magellas", name = "Alto explorador Magellas", note = "dirige la Liga" },
	},
})

Translate("esMX", "senator-barin-redstone", {
	title = "Senador Barin Redstone",
	subtitle = "Senador de Forjaz",
	found = "El High Seat",
	hint = "Encuentre al senador avinagrado en la corte del rey.",
	allegiance = "Senado de Forjaz",
	aliases = { "Barin Redstone" },
	sections = {
		{
			title = "Resumen",
			text = [=[Barin Redstone ocupa un escaño en el Senado de {link:ironforge}Forjaz{/link} y asiste a la corte del rey en {link:high-seat}el High Seat{/link}. Se le conoce por su carácter avinagrado. Cuando llegó de {link:kharanos}Kharanos{/link} un informe que invocaba la autoridad del propio rey para trabajos sobre el terreno, Redstone se indignó tanto con el autor como con el rey, y advirtió que al Senado no le agradaría.]=],
		},
		{
			title = "Importancia",
