		},
	},
	mentions = {
		{ text = "Los informes" },
	},
	bonds = {
		{ id = "senir-whitebeard", name = "Senir Whitebeard", note = "escribió el informe" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "su rey" },
	},
})

Translate("esMX", "afadra-dunwall", {
	title = "Afadra Dunwall",
	subtitle = "Tradicionalista de Forjaz",
	found = "Old Ironforge, bajo el High Seat",
	hint = [=[Busque a la tradicionalista que cuida el camino que baja al Hall of Thanes.]=],
	allegiance = "Reino de Forjaz",
	aliases = { "Afadra" },
	sections = {
		{
			title = "Resumen",
			text = [=[Afadra Dunwall es una tradicionalista de {link:ironforge}Forjaz{/link}, una de las guardianas que cuidan las tumbas del {link:hall-of-thanes}Hall of Thanes{/link}. De las criptas de abajo han llegado ruidos extraños, y los espíritus de los muertos, que tienen el sueño ligero, han despertado. Afadra quiere que vuelvan a descansar. También quiere que los demás guardianes dejen de negarse a cumplir sus deberes por culpa de los fantasmas.]=],
		},
		{
			title = "Importancia",
			text = [=[Afadra es una de las pocas que aún guardan a los muertos más antiguos de {link:ironforge}Forjaz{/link}. Su deber se ha vuelto peligroso.]=],
		},
	},
	mentions = {
		{ text = "Los muertos inquietos" },
	},
	bonds = {
		{ id = "thom-filch", name = "Thom Filch", note = "otro vigilante de las criptas" },
	},
})

Translate("esMX", "thom-filch", {
	title = "Thom Filch",
	subtitle = "El gnomo de las criptas",
	found = "Old Ironforge, bajo el High Seat",
	hint = [=[Encuentre al gnomo de Old Ironforge que patrullaba donde no debía.]=],
	allegiance = "Desconocida",
	sections = {
		{
			title = "Resumen",
			text = [=[Thom Filch es un {link:gnomes}gnomo{/link} que, según sus propias palabras, patrullaba las criptas bajo {link:ironforge}Forjaz{/link} cuando los {link:dark-iron-dwarves}Hierro Negro{/link} irrumpieron desde la roca en máquinas topo. Quiere que se recuperen las reliquias inestimables de las criptas. Las llama botín, luego herencias culturales, y promete que cada una será catalogada y devuelta a su lugar. Pocos de los que lo oyen se lo creen.]=],
		},
		{
			title = "Importancia",
			text = [=[Thom Filch fue el primero en ver a los {link:dark-iron-dwarves}Hierro Negro{/link} subir a las criptas, hiciera lo que hiciera él allí en ese momento.]=],
		},
	},
	mentions = {
		{ text = "Herencias importantes" },
	},
	bonds = {
		{ id = "afadra-dunwall", name = "Afadra Dunwall", note = "guarda las tumbas por las que él merodea" },
	},
})
